-- ============================================================
--  Тема «Пасив і Causative (Passive Voice / Causative Form)»: теорія у кроковому форматі + вправи
--  Згенеровано з mig/passive.js — вручну не редагувати.
--  Потребує 06_theory_structure.sql. Повторний запуск безпечний.
-- ============================================================
begin;

alter table public.topics        add column if not exists subtopics jsonb not null default '[]'::jsonb;
alter table public.theory_blocks add column if not exists subtopic  text;
alter table public.exercises     add column if not exists subtopic  text;

create unique index if not exists uq_exercises_legacy_shared
  on public.exercises (legacy_id) where student_id is null;
-- тип вправи «translate» (переклад і письмо) дозволено в exercises.type
alter table public.exercises drop constraint if exists exercises_type_check;
alter table public.exercises add constraint exercises_type_check
  check (type in ('order', 'choice', 'gap', 'cross', 'abcd', 'translate'));
alter table public.theory_blocks drop constraint if exists theory_blocks_kind_check;
alter table public.theory_blocks add constraint theory_blocks_kind_check
  check (kind in ('prose', 'hero', 'cases', 'formula', 'traps', 'pairs'));

insert into public.topics (slug, title, description, position, subtopics)
values ($g0$passive$g0$, $g1$Пасив і Causative (Passive Voice / Causative Form)$g1$, $g2$Passive Voice і Causative Form: be + V3 у всіх часах, by і with, пасив у питаннях і з hear / see / make, безособові конструкції, have / get something done. Є вправи на переписування речень і переклад із перевіркою та поясненням помилок.$g2$, 16, $g3$[{"slug":"pas_form","title":"Passive Voice: утворення й вживання","description":"Be + V3 у всіх часах і модальних конструкціях, коли пасив доречний, by і with, типові помилки."},{"slug":"pas_trans","title":"З активу в пасив і навпаки","description":"Як перебудувати речення: два додатки, дієслова з прийменником, питання, hear / see / make / help, безособові конструкції."},{"slug":"pas_caus","title":"Causative: have something done","description":"Коли ми домовляємося, щоб щось зробив хтось інший: have / get + додаток + V3 у всіх часах, а також неприємності, що трапилися з нами."}]$g3$::jsonb)
on conflict (slug) do update set title = excluded.title,
  description = excluded.description, position = excluded.position, subtopics = excluded.subtopics;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g4$pv_1$g4$, $g5$Пасив: be + V3 у всіх часах$g5$, $g6$elementary$g6$, $g7$formula$g7$, $g8${"step":"Passive Voice","kicker":"Як утворюється","lead":"У пасиві головне — <b>що відбувається з предметом або особою</b>, а не хто діє. Пасив утворюємо від <b>перехідних дієслів</b> (тих, після яких може стояти додаток): потрібна форма <b>to be</b> у тому часі, що й в активі, плюс <b>третя форма смислового дієслова (V3)</b>.","tiles":[{"role":"підмет","label":"що зазнає дії","tone":"noun"},{"role":"be","label":"у потрібному часі","tone":"colour"},{"role":"V3","label":"past participle","tone":"origin"}],"legend":[{"tone":"noun","label":"Це додаток з активного речення: <i>a lecture</i>"},{"tone":"colour","label":"Час змінюється лише на дієслові be: is / was / will be / has been"},{"tone":"origin","label":"Смислове дієслово завжди у третій формі: given, written, built"}],"examples":[{"text":"Lectures <b>are given</b>.","plain":"Lectures are given.","note":"Present Simple"},{"text":"A lecture <b>is being given</b>.","plain":"A lecture is being given.","note":"Present Continuous"},{"text":"A lecture <b>was given</b>.","plain":"A lecture was given.","note":"Past Simple"},{"text":"A lecture <b>has been given</b>.","plain":"A lecture has been given.","note":"Present Perfect"},{"text":"A lecture <b>will be given</b>.","plain":"A lecture will be given.","note":"Future Simple"},{"text":"A lecture <b>must be given</b>.","plain":"A lecture must be given.","note":"модальне дієслово"}],"note":"Present Perfect Continuous, Future Continuous і Past Perfect Continuous у пасиві зазвичай не вживаємо. У розмовній мові замість be іноді стоїть <b>get</b>, коли щось відбувається випадково: <i>She'll get in trouble if she goes on driving like that.</i>","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Форма</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Active</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Passive</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Present Simple</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">He gives lectures.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Lectures <b>are given</b>.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Present Continuous</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">He is giving a lecture.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">A lecture <b>is being given</b>.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Past Simple</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">He gave a lecture.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">A lecture <b>was given</b>.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Past Continuous</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">He was giving a lecture.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">A lecture <b>was being given</b>.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Future Simple</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">He will give a lecture.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">A lecture <b>will be given</b>.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Present Perfect</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">He has given a lecture.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">A lecture <b>has been given</b>.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Past Perfect</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">He had given a lecture.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">A lecture <b>had been given</b>.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Future Perfect</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">He will have given a lecture.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">A lecture <b>will have been given</b>.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Present Infinitive</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">He should give a lecture.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">A lecture <b>should be given</b>.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Perfect Infinitive</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">He should have given a lecture.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">A lecture <b>should have been given</b>.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">-ing form</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She remembers him giving a lecture.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She remembers a lecture <b>being given</b>.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Perfect -ing form</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Having given the lecture, …</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">The lecture <b>having been given</b>, …</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Модальні дієслова</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">He must give a lecture.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">A lecture <b>must be given</b>.</td></tr></tbody>\n</table></div>"}]}$g8$::jsonb, null, 0, $g9$pas_form$g9$
from public.topics where slug = $g10$passive$g10$
