insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g11$pv_2$g11$, $g12$Коли вживаємо пасив$g12$, $g13$elementary$g13$, $g14$cases$g14$, $g15${"kicker":"Чотири причини","lead":"Пасив обираємо тоді, коли виконавець дії не головний у розповіді. Він може бути невідомим, неважливим, очевидним або навмисно виділеним.","cards":[{"icon":"?","title":"Виконавець невідомий, неважливий або очевидний","text":"Ми не називаємо, хто діє, бо цього ніхто не знає або це зрозуміло з контексту.","example":"Her flat <b>was broken into</b> yesterday. (очевидно, що злодієм)","examplePlain":"Her flat was broken into yesterday. (очевидно, що злодієм)"},{"icon":"!","title":"Виконавця потрібно підкреслити","text":"Якщо хочемо виділити, хто саме це зробив, то додаємо <b>by + виконавець</b> наприкінці речення.","example":"Her wedding dress <b>was delivered</b> to her <b>by the dressmaker herself</b>.","examplePlain":"Her wedding dress was delivered to her by the dressmaker herself."},{"icon":"✉","title":"Формальність і ввічливість","text":"Пасив звучить менш різко, ніж пряме звинувачення з you.","example":"My dress <b>has been ruined</b>. (ввічливіше, ніж You have ruined my dress.)","examplePlain":"My dress has been ruined. (ввічливіше, ніж You have ruined my dress.)"},{"icon":"§","title":"Цікавить сама дія, а не виконавець","text":"Новини, офіційні оголошення, інструкції, описи процесів, заголовки, реклама.","example":"The meeting <b>will be held</b> tomorrow.","examplePlain":"The meeting will be held tomorrow."}]}$g15$::jsonb, null, 1, $g16$pas_form$g16$
