insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g18$pv_3$g18$, $g19$By, with і пропуск виконавця$g19$, $g20$intermediate$g20$, $g21$cases$g21$, $g22${"kicker":"Виконавець і знаряддя","lead":"Після пасивної форми ми можемо назвати того, хто діє, або те, чим діє, але найчастіше цю частину просто пропускаємо.","cards":[{"icon":"by","title":"By + виконавець: хто чи що діяло","text":"Додаємо by, коли виконавець важливий для змісту.","example":"She was knocked down <b>by a car</b>.","examplePlain":"She was knocked down by a car."},{"icon":"with","title":"With + знаряддя або матеріал","text":"Говоримо, чим скористалися, а також після coloured, crammed, crowded, filled, flavoured, packed.","example":"She was injured <b>with a hammer</b>. The room was filled <b>with smoke</b>.","examplePlain":"She was injured with a hammer. The room was filled with smoke."},{"icon":"∅","title":"By + виконавець пропускаємо","text":"Якщо виконавець невідомий, неважливий, очевидний або це слова someone, people, I, they тощо.","example":"They revealed the truth. → The truth <b>was revealed</b>. (by them відкидаємо)","examplePlain":"They revealed the truth. → The truth was revealed. (by them відкидаємо)"},{"icon":"?","title":"У питаннях who / whom / which by не відкидаємо","text":"Прийменник by стоїть наприкінці питання.","example":"Who gave you this information? → Who <b>were you given this information by</b>?","examplePlain":"Who gave you this information? → Who were you given this information by?"}]}$g22$::jsonb, null, 2, $g23$pas_form$g23$
from public.topics where slug = $g24$passive$g24$
