insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g25$pv_4$g25$, $g26$Типові помилки в пасиві$g26$, $g27$intermediate$g27$, $g28$traps$g28$, $g29${"kicker":"Захист від помилок","lead":"Найчастіші проблеми — друга форма замість третьої, пасив від неперехідного дієслова й нехтування формою be.","items":[{"title":"Друга форма замість третьої","bad":"The letter was wrote yesterday.","good":"The letter <b>was written</b> yesterday.","goodPlain":"The letter was written yesterday.","rule":"Після be — завжди V3: written, given, taken, stolen."},{"title":"Пасив від неперехідного дієслова","bad":"An accident was happened.","good":"An accident <b>happened</b>.","goodPlain":"An accident happened.","rule":"Happen, arrive, die, fall, sleep — неперехідні, пасиву від них немає."},{"title":"Не той час be","bad":"My car repaired now.","good":"My car <b>is being repaired</b> now.","goodPlain":"My car is being repaired now.","rule":"Тривала дія зараз: am/is/are + being + V3."},{"title":"Забули be","bad":"The house built in 1990.","good":"The house <b>was built</b> in 1990.","goodPlain":"The house was built in 1990.","rule":"Без be пасиву немає: потрібне було, є або буде."},{"title":"Модальне дієслово без be","bad":"The work must finished by noon.","good":"The work must <b>be finished</b> by noon.","goodPlain":"The work must be finished by noon.","rule":"Модальне + be + V3: must be finished, should have been done."}]}$g29$::jsonb, null, 3, $g30$pas_form$g30$
