insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g32$pv_5$g32$, $g33$Як перебудувати речення з активу в пасив$g33$, $g34$intermediate$g34$, $g35$cases$g35$, $g36${"kicker":"Алгоритм і особливі випадки","lead":"Додаток активного речення стає підметом пасиву, дієслово набуває форми <b>be + V3</b>, а підмет активу, якщо він потрібен, стає виконавцем із <b>by</b>.","cards":[{"icon":"1","title":"Три кроки","text":"Додаток → підмет. Дієслово → be (у тому ж часі) + V3. Підмет → by + виконавець або зникає.","example":"John <b>posted</b> the letters. → The letters <b>were posted</b> by John.","examplePlain":"John posted the letters. → The letters were posted by John."},{"icon":"2","title":"Два додатки: give, offer, tell","text":"Зазвичай пасив починаємо з особи, а не з речі.","example":"They offered Ann a bunch of flowers. → <b>Ann was offered</b> a bunch of flowers. (частіше, ніж A bunch of flowers was offered to Ann.)","examplePlain":"They offered Ann a bunch of flowers. → Ann was offered a bunch of flowers. (частіше, ніж A bunch of flowers was offered to Ann.)"},{"icon":"3","title":"Дієслово з прийменником","text":"Прийменник або частка лишається одразу після дієслова.","example":"She took down the minutes. → The minutes <b>were taken down</b>.","examplePlain":"She took down the minutes. → The minutes were taken down."},{"icon":"4","title":"Hear, help, make, see + to","text":"В активі після них інфінітив без to, у пасиві — з to.","example":"She made me work overtime. → I was made <b>to work</b> overtime.","examplePlain":"She made me work overtime. → I was made to work overtime."},{"icon":"5","title":"Hear, see, watch + -ing","text":"Якщо в активі був дієприкметник, у пасиві він лишається.","example":"We saw her crying. → She was seen <b>crying</b>.","examplePlain":"We saw her crying. → She was seen crying."},{"icon":"6","title":"Заперечення, питання й модальні","text":"Допоміжні дієслова ставимо на звичні місця, змінюється лише основна частина.","example":"Why didn't they give her the job? → Why <b>wasn't she given</b> the job?","examplePlain":"Why didn't they give her the job? → Why wasn't she given the job?"}]}$g36$::jsonb, null, 4, $g37$pas_trans$g37$
