insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g39$pv_6$g39$, $g40$Складніші пасивні конструкції$g40$, $g41$advanced$g41$, $g42$cases$g42$, $g43${"kicker":"Для впевненого рівня","lead":"Пасив легко вбудовується в інфінітив, форму на -ing, модальні дієслова і безособові звороти.","cards":[{"icon":"to","title":"Пасивний інфінітив: to be + V3","text":"Після ought to, hope, want, expect і подібних.","example":"Teachers ought <b>to be paid</b> a higher salary.","examplePlain":"Teachers ought to be paid a higher salary."},{"icon":"pf","title":"Перфектний інфінітив: have been + V3","text":"Про те, що мало бути зроблено в минулому.","example":"Your application should <b>have been handed in</b> last Monday.","examplePlain":"Your application should have been handed in last Monday."},{"icon":"ing","title":"Пасив на -ing: being + V3","text":"Після like, hate, can't bear, enjoy.","example":"I hate <b>being told</b> lies. She likes <b>being taken</b> to the theatre.","examplePlain":"I hate being told lies. She likes being taken to the theatre."},{"icon":"it","title":"Безособові звороти: is said / believed to","text":"Начебто «кажуть, вважають». Корисні в новинах.","example":"Holland <b>is said to be</b> one of the prettiest countries in Europe.","examplePlain":"Holland is said to be one of the prettiest countries in Europe."},{"icon":"be to","title":"Be + to + V: запланована дія","text":"Офіційна домовленість чи наказ; поруч із пасивом: is to be + V3.","example":"A new breed of cow <b>is to be introduced</b> into the country.","examplePlain":"A new breed of cow is to be introduced into the country."},{"icon":"get","title":"Get замість be","text":"У розмовній мові, коли щось відбувається ненавмисно чи раптово.","example":"She'll <b>get</b> in trouble if she goes on driving like that.","examplePlain":"She'll get in trouble if she goes on driving like that."}]}$g43$::jsonb, null, 5, $g44$pas_trans$g44$
