insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g46$pv_7$g46$, $g47$Causative: have something done$g47$, $g48$elementary$g48$, $g49$formula$g49$, $g50${"step":"Causative","kicker":"Як утворюється","lead":"Causative (пасивна каузація) говорить, що <b>ми домовляємося, щоб роботу зробив хтось інший</b>. Ми використовуємо <b>have + додаток + V3</b>, де have змінюється за часом.","tiles":[{"role":"підмет","label":"хто замовляє","tone":"noun"},{"role":"have","label":"у потрібному часі","tone":"colour"},{"role":"додаток","label":"що саме","tone":"origin"},{"role":"V3","label":"зроблено","tone":"age"}],"legend":[{"tone":"noun","label":"Підмет не виконує роботу сам: <i>She had a dress made</i>"},{"tone":"colour","label":"Have змінюємо за часом: has made / had / will have / is having"},{"tone":"origin","label":"Додаток стоїть між have і V3"},{"tone":"age","label":"Смислове дієслово — третя форма: made, cut, painted, repaired"}],"examples":[{"text":"He asked Sally to type the letters. He <b>had the letters typed</b>.","plain":"He asked Sally to type the letters. He had the letters typed.","note":"сам не друкував"},{"text":"She <b>is having a dress made</b>.","plain":"She is having a dress made.","note":"Present Continuous"},{"text":"She <b>will have a dress made</b>.","plain":"She will have a dress made.","note":"Future Simple"},{"text":"She <b>has had a dress made</b>.","plain":"She has had a dress made.","note":"Present Perfect"},{"text":"She likes <b>having dresses made</b>.","plain":"She likes having dresses made.","note":"-ing form"}],"note":"Заперечення й питання з have утворюємо через <b>do / does / did</b>: <i>He doesn't have his shirts ironed. Did he have the brakes checked?</i> Замість have часто стоїть <b>get</b>: <i>Did you have / get your nails polished?</i>","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Форма</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Active</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Causative</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Present Simple</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She makes dresses.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She <b>has</b> dresses made.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Present Continuous</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She is making a dress.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She <b>is having</b> a dress made.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Past Simple</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She made a dress.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She <b>had</b> a dress made.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Past Continuous</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She was making a dress.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She <b>was having</b> a dress made.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Future Simple</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She will make a dress.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She <b>will have</b> a dress made.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Future Continuous</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She will be making a dress.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She <b>will be having</b> a dress made.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Present Perfect</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She has made a dress.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She <b>has had</b> a dress made.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Present Perfect Continuous</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She has been making dresses.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She <b>has been having</b> dresses made.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Past Perfect</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She had made a dress.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She <b>had had</b> a dress made.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Past Perfect Continuous</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She had been making dresses.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She <b>had been having</b> dresses made.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">Infinitive</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She can make dresses.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She can <b>have</b> dresses made.</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">-ing form</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She likes making dresses.</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">She likes <b>having</b> dresses made.</td></tr></tbody>\n</table></div>"}]}$g50$::jsonb, null, 6, $g51$pas_caus$g51$
