insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g53$pv_8$g53$, $g54$Коли вживаємо causative$g54$, $g55$intermediate$g55$, $g56$cases$g56$, $g57${"kicker":"Послуги й неприємності","lead":"Causative схожий на пасив, бо виконавець роботи часто не названий. Але в ньому підмет — той, хто <b>замовив або пережив</b> дію.","cards":[{"icon":"✂","title":"Послуга: хтось робить це для нас","text":"Перукар, механік, майстер, кур'єр: ми платимо або просимо, а роботу виконують інші.","example":"I <b>had my hair cut</b> yesterday. (перукар стриг, а не я)","examplePlain":"I had my hair cut yesterday. (перукар стриг, а не я)"},{"icon":"~","title":"Get замість have","text":"Більш розмовний варіант; значення те саме.","example":"Did you <b>get your nails polished</b>?","examplePlain":"Did you get your nails polished?"},{"icon":"!","title":"Неприємність, що трапилась із нами","text":"Без нашого бажання: травма, крадіжка, поломка. Causative замінює пасив.","example":"He <b>had his nose broken</b> in a fight. (= His nose was broken in a fight.)","examplePlain":"He had his nose broken in a fight. (= His nose was broken in a fight.)"},{"icon":"=","title":"Різниця з активом","text":"<i>She made a dress</i> означає, що сама шила, а <i>She had a dress made</i> — що це зробив для неї хтось інший.","example":"She <b>had</b> the house <b>painted</b>. (малярі)","examplePlain":"She had the house painted. (малярі)"}]}$g57$::jsonb, null, 7, $g58$pas_caus$g58$
