insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g60$pv_9$g60$, $g61$Типові помилки в causative$g61$, $g62$intermediate$g62$, $g63$traps$g63$, $g64${"kicker":"Захист від помилок","lead":"Українське «я підстриг волосся» не каже, хто стриг. В англійській є дві різні форми: сам чи хтось інший.","items":[{"title":"Сам чи перукар","bad":"I cut my hair yesterday. (у перукарні)","good":"I <b>had my hair cut</b> yesterday.","goodPlain":"I had my hair cut yesterday.","rule":"Якщо стриг перукар, то потрібен causative: have + hair + cut."},{"title":"Інфінітив замість V3","bad":"She had her car repair.","good":"She had her car <b>repaired</b>.","goodPlain":"She had her car repaired.","rule":"Після додатка стоїть V3: repaired, cut, painted, delivered."},{"title":"Питання й заперечення","bad":"Had he his car repaired?","good":"<b>Did</b> he <b>have</b> his car repaired?","goodPlain":"Did he have his car repaired?","rule":"Have у causative — звичайне дієслово: do / does / did + have."},{"title":"Не той час have","bad":"She had a dress made now.","good":"She <b>is having</b> a dress made now.","goodPlain":"She is having a dress made now.","rule":"Тривала дія зараз: am/is/are having + V3."},{"title":"Мінімальна різниця: V3 vs V-ing","bad":"He had the barber cutting his hair.","good":"He <b>had his hair cut</b>.","goodPlain":"He had his hair cut.","rule":"Для послуги потрібне V3 (cut), а не V-ing."}]}$g64$::jsonb, null, 8, $g65$pas_caus$g65$
