  ($g967$pas_ex8_4$g967$, $g968$translate$g968$, $g969$intermediate$g969$, $g970${"id":"pas_ex8_4","level":"intermediate","group":8,"gord":8,"no":4,"groupTitle":"Exercise 6","instruction":"Write the sentences in the causative, as in the example. Answer the question.","kind":"rewrite","src":"Someone will repair our leaking roof. What will we do?","answers":["We will have our leaking roof repaired.","We will get our leaking roof repaired.","We'll have our leaking roof repaired.","We'll get our leaking roof repaired.","We will have our roof repaired.","We will get our roof repaired.","We'll have our roof repaired.","We'll get our roof repaired."],"traps":[],"explanation":"Causative Future: will have our roof repaired."}$g970$, 92, $g971$pas_caus$g971$),
  ($g972$pas_ex8_5$g972$, $g973$translate$g973$, $g974$intermediate$g974$, $g975${"id":"pas_ex8_5","level":"intermediate","group":8,"gord":8,"no":5,"groupTitle":"Exercise 6","instruction":"Write the sentences in the causative, as in the example. Answer the question.","kind":"rewrite","src":"Someone cut the lawn for them while they were away. What did they do?","answers":["They had the lawn cut while they were away.","They got the lawn cut while they were away."],"traps":[],"explanation":"Causative Past Simple: had the lawn cut."}$g975$, 93, $g976$pas_caus$g976$),
