  ($g982$pas_ex8_7$g982$, $g983$translate$g983$, $g984$advanced$g984$, $g985${"id":"pas_ex8_7","level":"advanced","group":8,"gord":8,"no":7,"groupTitle":"Exercise 6","instruction":"Write the sentences in the causative, as in the example. Answer the question.","kind":"rewrite","src":"A builder will do up Jan's attic. What will Jan do?","answers":["He will have his attic done up.","He will have her attic done up.","He will get his attic done up.","He will get her attic done up.","She will have his attic done up.","She will have her attic done up.","She will get his attic done up.","She will get her attic done up.","He'll have his attic done up.","He'll have her attic done up.","He'll get his attic done up.","He'll get her attic done up.","She'll have his attic done up.","She'll have her attic done up.","She'll get his attic done up.","She'll get her attic done up."],"traps":[],"explanation":"Causative Future: will have his / her attic done up. Фразове дієслово done up."}$g985$, 95, $g986$pas_caus$g986$),
  ($g987$pas_ex8_8$g987$, $g988$translate$g988$, $g989$intermediate$g989$, $g990${"id":"pas_ex8_8","level":"intermediate","group":8,"gord":8,"no":8,"groupTitle":"Exercise 6","instruction":"Write the sentences in the causative, as in the example. Answer the question.","kind":"rewrite","src":"Someone is designing some furniture for him. What is he doing?","answers":["He is having some furniture designed.","He is getting some furniture designed.","He's having some furniture designed.","He's getting some furniture designed."],"traps":[],"explanation":"Causative Present Continuous: is having some furniture designed."}$g990$, 96, $g991$pas_caus$g991$),
  ($g992$pas_ex8_9$g992$, $g993$translate$g993$, $g994$intermediate$g994$, $g995${"id":"pas_ex8_9","level":"intermediate","group":8,"gord":8,"no":9,"groupTitle":"Exercise 6","instruction":"Write the sentences in the causative, as in the example. Answer the question.","kind":"rewrite","src":"A detective investigated the case for her. What did she do?","answers":["She had the case investigated .","She had the case investigated by a detective.","She got the case investigated .","She got the case investigated by a detective."],"traps":[],"explanation":"Causative Past Simple: had the case investigated."}$g995$, 97, $g996$pas_caus$g996$),
  ($g997$pas_ex8_10$g997$, $g998$translate$g998$, $g999$advanced$g999$, $g1000${"id":"pas_ex8_10","level":"advanced","group":8,"gord":8,"no":10,"groupTitle":"Exercise 6","instruction":"Write the sentences in the causative, as in the example. Answer the question.","kind":"rewrite","src":"Someone has written the actor's life story for him. What has he done?","answers":["He has had his life story written.","He has got his life story written.","He has had his life story written .","He has had his life story written by someone.","He has got his life story written .","He has got his life story written by someone."],"traps":[],"explanation":"Causative Present Perfect: has had his life story written."}$g1000$, 98, $g1001$pas_caus$g1001$),
